local delay=require("delay")local gpio=require("gpio")local capability=require("capability")local PIN={HEATER=14,BUTTON=11,DHT=9}local CFG={lm=2000,t_min=37.5,t_max=38.5}local FEISHU="ou_XXXXXXXXXXXXXXXXXXXXXXXX"local g={running=true,ht=0,lt=nil,lh=nil,inc_start=0,inc_days=0}local function sd(ms)ms=math.floor(ms+0.5)if ms<=0 then return end while ms>0 do local s=math.min(ms,10)delay.delay_ms(s)ms=ms-s end end local function gg(p)local ok,v=pcall(gpio.get_level,p)if ok then return v end return nil end local function gs(p,v)pcall(gpio.set_level,p,v)end local function gi(p)pcall(gpio.set_direction,p,"input")end local function go(p)pcall(gpio.set_direction,p,"output")end local function txt(m)pcall(capability.call,"feishu_send_message",{message=m},{channel="feishu",chat_id=FEISHU,source_cap="lua_wildlife_monitor"})end local function rdDHT11(pin)gpio.set_direction(pin,"output")gpio.set_level(pin,0)delay.delay_ms(20)gpio.set_direction(pin,"input")local t=0 while gpio.get_level(pin)==1 do t=t+1 if t>1000 then return nil end end t=0 while gpio.get_level(pin)==0 do t=t+1 if t>1000 then return nil end end t=0 while gpio.get_level(pin)==1 do t=t+1 if t>1000 then return nil end end local data={}for i=1,40 do t=0 while gpio.get_level(pin)==0 do t=t+1 if t>1000 then return nil end end local ht=0 while gpio.get_level(pin)==1 do ht=ht+1 if ht>1000 then return nil end end data[i]=(ht>8)and 1 or 0 end local hi,hd,ti,td,cs=0,0,0,0,0 for i=1,8 do hi=hi*2+data[i]end for i=9,16 do hd=hd*2+data[i]end for i=17,24 do ti=ti*2+data[i]end for i=25,32 do td=td*2+data[i]end for i=33,40 do cs=cs*2+data[i]end if(hi+hd+ti+td)%256~=cs then return nil end return ti+td/10,hi+hd/10 end local function rdDHT()for i=1,3 do local t,h=rdDHT11(PIN.DHT)if t then g.lt,g.lh=t,h return t,h end sd(100)end return g.lt,g.lh end local function sH(on)g.ht=on and 1 or 0 gs(PIN.HEATER,on and 1 or 0)end local function btnPressed()local b1=gg(PIN.BUTTON)if not b1 or b1~=0 then return false end sd(50)local b2=gg(PIN.BUTTON)return b2 and b2==0 end local function runAIBlogger()local ok,blog=pcall(dofile,"/fatfs/scripts/user/AI_blogger.lua")if ok and blog and blog.run then local sok=pcall(blog.run,"孵化器",{t_min=37.5,t_max=38.5,h_min=50,h_max=60})if not sok then txt("🥚【AI博主】\n⚠️运行出错\n⏰"..os.date("%Y-%m-%d %H:%M:%S"))end end end gi(PIN.BUTTON)go(PIN.HEATER)gi(PIN.DHT)g.inc_start=os.time()txt("🥚【孵蛋模式】\n━━━━━━━━\n🟢孵蛋流程已启动\n🌡️温度:37.5-38.5°C\n💧湿度:50%-60%\n⏱️目标:21天\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n━━━━━━━━\n🔘按键可随时退出")local blogFirst=false local blogLast=0 local blogInt=240000 while g.running do local t,h=rdDHT()local now=os.time()local elapsed=now-g.inc_start local days=math.floor(elapsed/86400)if days>g.inc_days then g.inc_days=days txt("🥚【孵蛋进度】\n━━━━━━━━\n📅第"..(days+1).."天/共21天\n🌡️温度:"..tostring(t or"--").."°C\n💧湿度:"..tostring(h or"--").."%\n⏰"..os.date("%Y-%m-%d %H:%M:%S"))end if t then if t<37.5 then sH(true)elseif t>38.5 then sH(false)end end if elapsed>=1814400 then txt("🥚【孵蛋完成】\n━━━━━━━━\n✅21天孵蛋周期完成\n🐣请检查孵化情况\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n━━━━━━━━")break end if btnPressed() then txt("🥚【孵蛋中断】\n━━━━━━━━\n🔘按键触发\n孵蛋流程被中断\n共进行"..days.."天\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n━━━━━━━━")break end local now2=os.time()*1000 if not blogFirst then blogFirst=true blogLast=now2 runAIBlogger()else if now2-blogLast>=blogInt then blogLast=now2 runAIBlogger()end end sd(CFG.lm)end sH(false)txt("🥚【孵蛋结束】\n━━━━━━━━\n🔴加热片已关闭\n⏰"..os.date("%Y-%m-%d %H:%M:%S").."\n━━━━━━━━")
